CREATE TABLE ops_task_runs (task_run_id uuid PRIMARY KEY, task_type text NOT NULL, business_date date NOT NULL, input_hash text NOT NULL, correlation_id text NOT NULL, attempt integer NOT NULL CHECK(attempt>=1), max_attempts integer NOT NULL CHECK(max_attempts>=attempt), status text NOT NULL CHECK(status IN ('PENDING','RUNNING','SUCCEEDED','FAILED_RETRYABLE','FAILED_FINAL','CANCELLED')), lease_owner text, lease_expires_at timestamptz, fencing_token integer NOT NULL CHECK(fencing_token>=0), started_at timestamptz, finished_at timestamptz, error_class text, previous_run_id uuid, UNIQUE(task_type,business_date,input_hash,attempt));
CREATE TABLE ops_outbox_events (event_id uuid PRIMARY KEY, event_type text NOT NULL, aggregate_id uuid NOT NULL, payload jsonb NOT NULL, schema_version integer NOT NULL CHECK(schema_version>=1), occurred_at timestamptz NOT NULL, recorded_at timestamptz NOT NULL, correlation_id text NOT NULL, causation_id uuid, status text NOT NULL CHECK(status IN ('PENDING','LEASED','DELIVERED','FAILED')), attempts integer NOT NULL CHECK(attempts>=0), lease_owner text, lease_expires_at timestamptz, delivered_at timestamptz);
CREATE INDEX ops_outbox_dispatch_idx ON ops_outbox_events(status,recorded_at);
CREATE TABLE ops_consumer_checkpoints (checkpoint_id uuid PRIMARY KEY, consumer text NOT NULL, event_id uuid NOT NULL, processed_at timestamptz NOT NULL, result_hash char(64) NOT NULL, UNIQUE(consumer,event_id));
CREATE TABLE ops_dataset_batches (batch_id uuid PRIMARY KEY, source text NOT NULL, dataset text NOT NULL, checksum text NOT NULL, window_start timestamptz NOT NULL, window_end timestamptz NOT NULL, status text NOT NULL CHECK(status IN ('STAGED','PUBLISHED','REJECTED')), quality text NOT NULL CHECK(quality IN ('PASS','FAIL','WARN')), published_at timestamptz, UNIQUE(source,dataset,checksum), CHECK(window_end>=window_start));
CREATE TABLE ops_configuration_versions (configuration_id uuid PRIMARY KEY, environment text NOT NULL, version integer NOT NULL CHECK(version>=1), values jsonb NOT NULL, secret_refs jsonb NOT NULL, effective_from timestamptz NOT NULL, effective_to timestamptz, content_hash char(64) NOT NULL, UNIQUE(environment,version), CHECK(effective_to IS NULL OR effective_to>effective_from));
CREATE TABLE ops_backup_records (backup_id uuid PRIMARY KEY, started_at timestamptz NOT NULL, finished_at timestamptz NOT NULL, succeeded boolean NOT NULL, checksum text NOT NULL, schema_version text NOT NULL, restored_at timestamptz);
CREATE TABLE ops_alert_records (alert_id uuid PRIMARY KEY, category text NOT NULL, message text NOT NULL, occurred_at timestamptz NOT NULL, correlation_id text NOT NULL, primary_delivered boolean NOT NULL, fallback_persisted boolean NOT NULL);
CREATE TABLE ops_audit_logs (audit_id uuid PRIMARY KEY, actor text NOT NULL, service text NOT NULL, command text NOT NULL, object_id uuid NOT NULL, result text NOT NULL, occurred_at timestamptz NOT NULL, correlation_id text NOT NULL);
